package com.lamggm.rospocket;

import android.content.Context;import android.view.*;import android.widget.*;import java.util.concurrent.*;import java.util.function.BooleanSupplier;
/** Separate read-only destination; one bounded decoder and one replaceable pending frame. */
final class LocationPanel extends LinearLayout {
 static final class Request {final LocationConfig config;Request(LocationConfig c){config=c;}}
 private volatile Request selected;private volatile boolean visible;private volatile long stream;private volatile MapGrid shown;
 private LocationConfig configured=new LocationConfig();private volatile boolean closed;private boolean decoding,uiQueued;private volatile long sequence;private Task pending;private Runnable pendingUi;
 private final ExecutorService decoder=Executors.newSingleThreadExecutor(r->{Thread t=new Thread(r,"pocket-map-decode");t.setDaemon(true);return t;});
 final LocationMapView surface;private TextView diagnostic;private String offerDetail="Descoberta ainda não disponível · QoS ofertado desconhecido.",tfDetail="TF ainda não observado",mapDetail="Mapa ainda não recebido";private long sourceStamp;private org.json.JSONArray offers;
 private final TextView status,pose;private final EditText topic,robotFrame,dynamicTf,staticTf;private final CheckBox reliable,retained;private Button follow;
 private static final class Task {final Request owner;final long epoch,sequence;final SensorPacket packet;final BooleanSupplier guard;Task(Request r,long e,long s,SensorPacket p,BooleanSupplier g){owner=r;epoch=e;sequence=s;packet=p;guard=g;}}
 LocationPanel(Context c){super(c);setOrientation(VERTICAL);setTag("location-page");TextView title=text("Localização",20);title.setPadding(0,0,0,dp(8));text("Mapa e pose · somente leitura",11);
  pose=text("Pose indisponível · aguardando mapa e TF",15);pose.setTag("location-pose");surface=new LocationMapView(c);addView(surface,new LayoutParams(-1,dp(Math.max(160,Math.min(360,getResources().getConfiguration().screenHeightDp-(getResources().getConfiguration().screenWidthDp>=600?310:360))))));surface.onPoseExpired(()->{tfDetail="Pose TF vencida · aguardando timestamp novo";pose.setText(tfDetail);refreshDiagnostic();});
  LinearLayout viewActions=new LinearLayout(c);int available=getResources().getConfiguration().screenWidthDp-(getResources().getConfiguration().screenWidthDp>=600?160:32);addView(viewActions,new LayoutParams(dp(Math.min(440,available)),dp(48)));button(viewActions,"Enquadrar","location-fit",surface::fit);button(viewActions,"−","location-zoom-out",()->surface.zoom(.5));button(viewActions,"+","location-zoom-in",()->surface.zoom(2));follow=button(viewActions,"Seguir robô","location-follow",()->{surface.follow(!surface.follow());follow.setSelected(surface.follow());UiTheme.apply(follow);});surface.onFollowChanged(()->{follow.setSelected(surface.follow());UiTheme.apply(follow);});
  status=text("Selecione um mapa em Explorar ou configure abaixo. Nenhuma pose é estimada pelo app.",12);status.setTag("location-status");
  LinearLayout settings=new LinearLayout(c);settings.setVisibility(GONE);Button settingsToggle=new VisualButton(c,"secondary",null);settingsToggle.setText("Fontes e ajustes ▾");settingsToggle.setTag("location-settings-toggle");settingsToggle.setContentDescription("Expandir ou recolher fontes e ajustes de localização");settingsToggle.setOnClickListener(v->{boolean open=settings.getVisibility()!=VISIBLE;settings.setVisibility(open?VISIBLE:GONE);settingsToggle.setText(open?"Fontes e ajustes ▴":"Fontes e ajustes ▾");settingsToggle.setSelected(open);UiTheme.apply(settingsToggle);});addView(settingsToggle,new LayoutParams(-1,dp(48)));settings.setOrientation(VERTICAL);settings.setTag("location-settings");settings.setPadding(dp(12),dp(12),dp(12),dp(12));addView(settings);topic=input(settings,"Tópico absoluto do mapa","/map","location-topic");robotFrame=input(settings,"Frame do robô","base_link","location-robot-frame");dynamicTf=input(settings,"Tópico TF dinâmico (vazio para não ler)","/tf","location-tf");staticTf=input(settings,"Tópico TF estático (vazio para não ler)","/tf_static","location-tf-static");
  reliable=new CheckBox(c);reliable.setText("Mapa reliable");reliable.setChecked(true);reliable.setTag("location-reliable");settings.addView(reliable);retained=new CheckBox(c);retained.setText("Mapa transient local (mapa retido)");retained.setChecked(true);retained.setTag("location-retained");settings.addView(retained);
  android.content.SharedPreferences display=c.getSharedPreferences("location-display",Context.MODE_PRIVATE);CheckBox trail=new CheckBox(c);trail.setText("Exibir rastro observado · até 256 posições");trail.setTag("location-trail");trail.setChecked(display.getBoolean("trail",true));surface.trailEnabled(trail.isChecked());trail.setOnCheckedChangeListener((b,on)->{surface.trailEnabled(on);display.edit().putBoolean("trail",on).apply();});settings.addView(trail);
  LinearLayout actions=new LinearLayout(c);settings.addView(actions);button(actions,"Observar","location-observe",()->{try{configure(controls());status.setText("Seleção local aplicada · aguardando conexão/mapa. Salve o perfil em Conexão para reter esta escolha.");}catch(IllegalArgumentException e){status.setText(e.getMessage());}});button(actions,"Parar","location-stop",()->{LocationConfig c0=configured;configure(new LocationConfig("",c0.robotFrame,c0.dynamicTf,c0.staticTf,c0.reliable,c0.retained));});
  Button details=new VisualButton(c,"secondary",null);details.setText("Por que não aparece?");details.setTag("location-diagnostics-toggle");details.setOnClickListener(v->{diagnostic.setVisibility(diagnostic.getVisibility()==VISIBLE?GONE:VISIBLE);refreshDiagnostic();});addView(details,new LayoutParams(-1,dp(48)));diagnostic=text("",12);diagnostic.setTag("location-diagnostics");diagnostic.setVisibility(GONE);refreshDiagnostic();
  text("Um leitor visual: mapa alterna com câmera/LiDAR. Mapa até 1 Mi células / 2048 por lado; sem tiles externos, comandos, rota ou costmap. Pose exige cadeia TF válida no frame do mapa. Mapa retido não significa localização atual.",12);
 }
 private int dp(float n){return Math.round(n*getResources().getDisplayMetrics().density);}
 private TextView text(String s,int size){TextView t=new TextView(getContext());t.setText(s);t.setTextSize(size);t.setTextColor(size>=15?VisualButton.ink(getContext()):VisualButton.muted(getContext()));t.setPadding(0,dp(6),0,dp(8));addView(t);return t;}
 private EditText input(LinearLayout parent,String hint,String value,String tag){TextView label=new TextView(getContext());label.setText(hint);label.setTextSize(12);label.setTextColor(VisualButton.muted(getContext()));parent.addView(label);EditText e=new EditText(getContext());e.setTag(tag);e.setHint(hint);e.setContentDescription(hint);e.setSingleLine();e.setText(value);e.setTextSize(14);e.setTextColor(VisualButton.ink(getContext()));e.setHintTextColor(VisualButton.muted(getContext()));parent.addView(e,new LayoutParams(-1,dp(52)));return e;}
 private Button button(LinearLayout row,String caption,String tag,Runnable r){Button b=new VisualButton(getContext(),"secondary",null);b.setText(caption);b.setTag(tag);b.setContentDescription(caption+" · localização somente leitura");b.setOnClickListener(v->r.run());row.addView(b,tag.startsWith("location-zoom-")?new LayoutParams(dp(48),dp(48)):new LayoutParams(0,dp(48),1));return b;}
 private static String wire(String text,boolean empty){String s=text.trim();if(empty&&s.isEmpty())return "";if(s.startsWith("rt/"))return LocationConfig.topic(s,false);if(!s.startsWith("/"))throw new IllegalArgumentException("Use tópico ROS absoluto, por exemplo /map");return LocationConfig.topic("rt"+s,false);}
 private static String ros(String wire){return wire.isEmpty()?"":wire.substring(2);}
 private LocationConfig controls(){return new LocationConfig(wire(topic.getText().toString(),false),robotFrame.getText().toString().trim(),wire(dynamicTf.getText().toString(),true),wire(staticTf.getText().toString(),true),reliable.isChecked(),retained.isChecked());}
 LocationConfig profile(){return configured;}
 void configure(LocationConfig c){configured=c;selected=c.wire.isEmpty()?null:new Request(c);topic.setText(c.wire.isEmpty()?"/map":ros(c.wire));robotFrame.setText(c.robotFrame);dynamicTf.setText(ros(c.dynamicTf));staticTf.setText(ros(c.staticTf));reliable.setChecked(c.reliable);retained.setChecked(c.retained);invalidateStream("Aguardando mapa e pose desta seleção");}
 void select(String w){try{LocationConfig c=controls();configure(new LocationConfig(w,c.robotFrame,c.dynamicTf,c.staticTf,c.reliable,c.retained));}catch(IllegalArgumentException e){status.setText(e.getMessage());}}
 void visible(boolean value){if(visible!=value){visible=value;invalidateStream(value?"Aguardando mapa desta sessão":"Localização fora da tela");}}
 boolean visible(){return visible;}
 Request desired(){return visible?selected:null;}
 long epoch(){return stream;}
 boolean current(Request r,long e){return !closed&&desired()==r&&stream==e;}
 MapGrid map(){return shown;}
 void invalidateStream(String reason){final long own; synchronized(this){own=++stream;sequence++;pending=null;pendingUi=null;shown=null;}Runnable clear=()->{if(stream==own){surface.clear();offers=null;mapDetail=reason;tfDetail="TF ainda não observado nesta seleção";sourceStamp=0;offerDetail=LocationDiagnostics.offers(configured,offers);pose.setText("Pose indisponível · aguardando TF");status.setText(reason);refreshDiagnostic();follow.setSelected(false);UiTheme.apply(follow);}};if(android.os.Looper.myLooper()==android.os.Looper.getMainLooper())clear.run();else queueUi(clear);}
 private boolean current(Task t){return current(t.owner,t.epoch)&&sequence==t.sequence&&t.guard.getAsBoolean();}
 boolean accept(Request r,long epoch,byte[] bytes,BooleanSupplier guard){try{SensorPacket p=new SensorPacket(bytes);if(!p.meta.optBoolean("running"))throw new IllegalArgumentException("Leitor de mapa inativo");if(!p.meta.optString("error").isEmpty()){error(r,epoch,p.meta.optString("error"),guard);return true;}if(!p.meta.has("kind"))return true;if(!"map".equals(p.meta.optString("kind")))throw new IllegalArgumentException("Payload não é mapa");synchronized(this){if(!current(r,epoch)||!guard.getAsBoolean())return true;pending=new Task(r,epoch,++sequence,p,guard);if(decoding)return true;decoding=true;}decoder.execute(this::drain);return true;}catch(Exception ex){error(r,epoch,"Mapa indisponível: "+ex.getMessage(),guard);return false;}}
 private void drain(){for(;;){final Task t;synchronized(this){t=pending;pending=null;if(t==null||closed){decoding=false;return;}}try{SensorPacket.Decoded d=t.packet.decode();synchronized(this){if(current(t))queueUi(()->{if(current(t)){boolean sameFrame=shown!=null&&shown.frame.equals(d.map.frame);shown=d.map;surface.map(d.map);if(!sameFrame){tfDetail="Aguardando TF no frame "+d.map.frame;sourceStamp=0;pose.setText(tfDetail);}mapDetail="Mapa recebido · frame "+d.map.frame;refreshDiagnostic();status.setText(d.map.width+" × "+d.map.height+" · "+String.format(java.util.Locale.ROOT,"%.4g m/célula",d.map.resolution)+" · frame "+d.map.frame+"\nMapa recebido, possivelmente retido; não é prova de pose atual.");}});}}catch(Exception ex){synchronized(this){if(current(t))error(t.owner,t.epoch,"Mapa inválido: "+ex.getMessage(),t.guard);}}}}
 void error(Request r,long epoch,String message,BooleanSupplier guard){synchronized(this){if(!current(r,epoch)||!guard.getAsBoolean())return;long own=++sequence;pending=null;shown=null;queueUi(()->{if(current(r,epoch)&&sequence==own&&guard.getAsBoolean()){surface.clear();mapDetail=message;tfDetail="Pose indisponível: mapa inválido/inativo";pose.setText("Pose indisponível");status.setText(message);refreshDiagnostic();}});}}
 void pose(Request r,long epoch,MapGrid map,RobotTf.Pose p){if(!current(r,epoch)||map==null||shown==null||!map.frame.equals(shown.frame))return;if(map.frame.equals(r.config.robotFrame)){surface.clearPose();tfDetail="Frame do robô igual ao mapa · selecione um frame distinto";pose.setText(tfDetail);refreshDiagnostic();return;}double[] m=p.transforms.get(r.config.robotFrame);if(!p.live||System.nanoTime()>p.deadline||m==null||Math.hypot(m[0],m[4])<1e-6){surface.clearPose();tfDetail=p.live?"Pose TF indisponível/vencida":p.status;pose.setText(tfDetail);pose.setTextColor(VisualButton.muted(getContext()));refreshDiagnostic();return;}double yaw=Math.atan2(m[4],m[0]);surface.pose(m[3],m[7],yaw,p.deadline);sourceStamp=p.stamp;tfDetail=p.status;pose.setTextColor(VisualButton.accent(getContext()));refreshDiagnostic();pose.setText(String.format(java.util.Locale.ROOT,"x %.3f m   y %.3f m   θ %.1f°\n%s · %s → %s",m[3],m[7],Math.toDegrees(yaw),p.stamp==0?"Pose estática observada":"Pose atual · recebida há "+Math.max(0,(System.nanoTime()-(p.deadline-RobotTf.MAX_AGE_NS))/1000000)+" ms",map.frame,r.config.robotFrame));}
 void discovery(org.json.JSONArray topics){offers=topics;offerDetail=LocationDiagnostics.offers(configured,offers);refreshDiagnostic();}
 private void refreshDiagnostic(){if(diagnostic==null)return;String value="Mapa: "+(configured.wire.isEmpty()?"não selecionado":ros(configured.wire))+"\n"+mapDetail+"\nTF dinâmico: "+(configured.dynamicTf.isEmpty()?"desligado":ros(configured.dynamicTf))+" · estático: "+(configured.staticTf.isEmpty()?"desligado":ros(configured.staticTf))+"\nCadeia: "+(shown==null?"frame do mapa ainda desconhecido":shown.frame)+" → "+configured.robotFrame+"\n"+tfDetail+(sourceStamp==0?"":"\nTimestamp ROS exato: "+sourceStamp+" ns (não comparado ao relógio do tablet)")+"\nQoS solicitado pelo mapa: "+(configured.reliable?"reliable":"best_effort")+" / "+(configured.retained?"transient_local":"volatile")+"\n"+offerDetail+"\nOfertas desconhecidas não garantem compatibilidade. Rede, tipo e outras políticas DDS também afetam entrega.";if(!android.text.TextUtils.equals(diagnostic.getText(),value))diagnostic.setText(value);}
 private void queueUi(Runnable r){synchronized(this){if(closed)return;pendingUi=r;if(uiQueued)return;uiQueued=true;}post(()->{Runnable next;synchronized(this){next=pendingUi;pendingUi=null;uiQueued=false;}if(next!=null)next.run();});}
 void dispose(){synchronized(this){closed=true;stream++;pending=null;pendingUi=null;shown=null;}surface.clear();decoder.shutdownNow();}
}
